//! C-alignment regression tests (step M1: the port of C's virtual machine, `sqliters_vdbe::vdbe`). The statements are
//! executed by the machine (the diagnostic switch, turned on for the test thread) and every expected row — including
//! the order of rows without ORDER BY, the order of equal sort keys and the rows printed before a run-time error — and
//! every error message is what the C shell SQLite 3.54.1 prints for the same statements (generated by
//! target/perf-work/m1/gen_tests_m1.py from target/perf-work/bin/sqlite3). Nothing here depends on files outside the
//! repository.
use crate::{Connection, StepResult};
use sqliters_types::Value;

fn text(v: &Value) -> String {
    match v {
        Value::Null => String::new(),
        Value::Integer(i) => i.to_string(),
        Value::Real(r) => sqliters_types::real_to_text(*r),
        Value::Text(s) => s.clone(),
        Value::Blob(b) => String::from_utf8_lossy(b).into_owned(),
    }
}

/// Runs `setup`, then every query on the machine: the rows as `a|b|c` and the error message that ended the statement.
fn check(setup: &[&str], cases: &[(&str, &[&str], Option<&str>)]) {
    let conn = Connection::open_in_memory().unwrap();
    for s in setup {
        conn.execute(s).unwrap();
    }
    let _on = crate::vdbe_host::ForceMachine::on();
    for (sql, want_rows, want_err) in cases {
        let before = crate::vdbe_host::machine_runs();
        let mut got: Vec<String> = Vec::new();
        let mut err: Option<String> = None;
        match conn.prepare(sql) {
            Ok(mut st) => loop {
                match st.step() {
                    Ok(StepResult::Row(r)) => got.push(r.values().iter().map(text).collect::<Vec<_>>().join("|")),
                    Ok(StepResult::Done) => break,
                    Err(e) => {
                        err = Some(e.message.clone());
                        break;
                    }
                }
            },
            Err(e) => err = Some(e.message.clone()),
        }
        assert_eq!(got, want_rows.iter().map(|s| (*s).to_owned()).collect::<Vec<_>>(), "rows of: {sql}");
        assert_eq!(err.as_deref(), *want_err, "error of: {sql}");
        assert!(crate::vdbe_host::machine_runs() > before, "not run by the machine: {sql}");
    }
}

#[test]
fn machine_full_scans_and_rowid_seeks() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b INT, c TEXT, d REAL, e)",
            "CREATE INDEX t_b ON t(b)",
            "CREATE INDEX t_cb ON t(c, b DESC)",
            "CREATE TABLE u(x, y TEXT COLLATE NOCASE, z NUMERIC)",
            "CREATE INDEX u_x ON u(x)",
            "CREATE TABLE p(k TEXT, j INT, v, PRIMARY KEY(k, j DESC)) WITHOUT ROWID",
            "INSERT INTO t VALUES(1,5,'abc',1.5,NULL),(2,3,'ABC',NULL,'e2'),(3,5,'b1',2.0,3),(4,NULL,'abc',0.5,x'6162'),(5,1,NULL,1e3,5.25),(6,3,'a0','7',6),(7,7,'',-0.0,'7'),(9,2,'b1',2.5,9),(10,5,'abd',NULL,NULL),(12,'12','12',12,12)",
            "INSERT INTO u VALUES(5,'Foo',1),(3,'foo','2.0'),(5,'BAR',NULL),(NULL,'bar',3),('5','baz',1e2),(7,NULL,'z'),(1,'Foo',0)",
            "INSERT INTO p VALUES('k1',1,'v1'),('k1',2,NULL),('k2',1,5),('k0',9,1.5),('k2',7,'v1')",
        ],
        &[
            ("SELECT * FROM t", &["1|5|abc|1.5|", "2|3|ABC||e2", "3|5|b1|2.0|3", "4||abc|0.5|ab", "5|1||1000.0|5.25", "6|3|a0|7.0|6", "7|7||0.0|7", "9|2|b1|2.5|9", "10|5|abd||", "12|12|12|12.0|12"], None),
            ("SELECT a, c FROM t WHERE a = 3", &["3|b1"], None),
            ("SELECT a FROM t WHERE a > 4.9", &["5", "6", "7", "9", "10", "12"], None),
            ("SELECT a FROM t WHERE a <= '6' ORDER BY a DESC", &["6", "5", "4", "3", "2", "1"], None),
            ("SELECT a FROM t WHERE a BETWEEN 2 AND 5.5", &["2", "3", "4", "5"], None),
            ("SELECT a FROM t WHERE rowid > 'abc'", &[], None),
            ("SELECT a FROM t WHERE a = 2.5", &[], None),
            ("SELECT a FROM t WHERE a IN (9, 1, 4, 100)", &["1", "4", "9"], None),
            ("SELECT a, typeof(e), length(c) FROM t WHERE a >= 9", &["9|integer|2", "10|null|3", "12|integer|2"], None),
            ("SELECT k, j FROM p", &["k0|9", "k1|2", "k1|1", "k2|7", "k2|1"], None),
            ("SELECT j FROM p WHERE k = 'k1'", &["2", "1"], None),
            ("SELECT k, j, v FROM p WHERE k > 'k0' AND j < 7", &["k1|2|", "k1|1|v1", "k2|1|5"], None),
        ],
    );
}

#[test]
fn machine_index_seeks_and_ranges() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b INT, c TEXT, d REAL, e)",
            "CREATE INDEX t_b ON t(b)",
            "CREATE INDEX t_cb ON t(c, b DESC)",
            "CREATE TABLE u(x, y TEXT COLLATE NOCASE, z NUMERIC)",
            "CREATE INDEX u_x ON u(x)",
            "CREATE TABLE p(k TEXT, j INT, v, PRIMARY KEY(k, j DESC)) WITHOUT ROWID",
            "INSERT INTO t VALUES(1,5,'abc',1.5,NULL),(2,3,'ABC',NULL,'e2'),(3,5,'b1',2.0,3),(4,NULL,'abc',0.5,x'6162'),(5,1,NULL,1e3,5.25),(6,3,'a0','7',6),(7,7,'',-0.0,'7'),(9,2,'b1',2.5,9),(10,5,'abd',NULL,NULL),(12,'12','12',12,12)",
            "INSERT INTO u VALUES(5,'Foo',1),(3,'foo','2.0'),(5,'BAR',NULL),(NULL,'bar',3),('5','baz',1e2),(7,NULL,'z'),(1,'Foo',0)",
            "INSERT INTO p VALUES('k1',1,'v1'),('k1',2,NULL),('k2',1,5),('k0',9,1.5),('k2',7,'v1')",
        ],
        &[
            ("SELECT a FROM t WHERE b = 5", &["1", "3", "10"], None),
            ("SELECT a, b FROM t WHERE b > 3", &["1|5", "3|5", "10|5", "7|7", "12|12"], None),
            ("SELECT a FROM t WHERE b IS NULL", &["4"], None),
            ("SELECT a FROM t WHERE b IN (1, 7, 3)", &["5", "2", "6", "7"], None),
            ("SELECT a FROM t WHERE c = 'abc' AND b < 9", &["1"], None),
            ("SELECT a FROM t WHERE c LIKE 'ab%'", &["2", "1", "4", "10"], None),
            ("SELECT a FROM t WHERE c GLOB 'b*'", &["3", "9"], None),
            ("SELECT a FROM t WHERE b = 5 OR c = 'b1'", &["1", "3", "10", "9"], None),
            ("SELECT b FROM t WHERE b >= '3'", &["3", "3", "5", "5", "5", "7", "12"], None),
            ("SELECT c, b FROM t WHERE c >= 'abc' ORDER BY c, b DESC", &["abc|5", "abc|", "abd|5", "b1|5", "b1|2"], None),
            ("SELECT count(*) FROM t WHERE b BETWEEN 2 AND 5", &["6"], None),
            ("SELECT x FROM u WHERE x = 5", &["5", "5"], None),
            ("SELECT x, y FROM u WHERE x > 1 ORDER BY x", &["3|foo", "5|Foo", "5|BAR", "7|", "5|baz"], None),
        ],
    );
}

