#[test]
fn machine_aggregates_without_group_by() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b INT, c TEXT, d REAL, e)",
            "CREATE INDEX t_b ON t(b)",
            "CREATE INDEX t_cb ON t(c, b DESC)",
            "CREATE TABLE u(x, y TEXT COLLATE NOCASE, z NUMERIC)",
            "CREATE INDEX u_x ON u(x)",
            "CREATE TABLE p(k TEXT, j INT, v, PRIMARY KEY(k, j DESC)) WITHOUT ROWID",
            "INSERT INTO t VALUES(1,5,'abc',1.5,NULL),(2,3,'ABC',NULL,'e2'),(3,5,'b1',2.0,3),(4,NULL,'abc',0.5,x'6162'),(5,1,NULL,1e3,5.25),(6,3,'a0','7',6),(7,7,'',-0.0,'7'),(9,2,'b1',2.5,9),(10,5,'abd',NULL,NULL),(12,'12','12',12,12)",
            "INSERT INTO u VALUES(5,'Foo',1),(3,'foo','2.0'),(5,'BAR',NULL),(NULL,'bar',3),('5','baz',1e2),(7,NULL,'z'),(1,'Foo',0)",
            "INSERT INTO p VALUES('k1',1,'v1'),('k1',2,NULL),('k2',1,5),('k0',9,1.5),('k2',7,'v1')",
        ],
        &[
            ("SELECT count(*), count(b), min(b), max(b) FROM t", &["10|9|1|12"], None),
            ("SELECT sum(b), total(d), avg(a) FROM t", &["43|1025.5|5.9"], None),
            ("SELECT min(c), max(c) FROM t", &["|b1"], None),
            ("SELECT max(y) FROM u", &["Foo"], None),
            ("SELECT min(y COLLATE BINARY), max(y) FROM u", &["BAR|Foo"], None),
            ("SELECT group_concat(c, '/') FROM t WHERE a < 6", &["abc/ABC/b1/abc"], None),
            ("SELECT count(DISTINCT b) FROM t", &["6"], None),
            ("SELECT count(*) FROM p WHERE v IS NULL", &["1"], None),
            ("SELECT max(a), c FROM t", &["12|12"], None),
            ("SELECT min(b), a FROM t WHERE b > 1", &["2|9"], None),
            ("SELECT count(*) FROM t WHERE 0", &["0"], None),
            ("SELECT sum(b) FROM t WHERE 0", &[""], None),
            ("SELECT max(x), min(x), nullif(max(x), 7) FROM u", &["5|1|5"], None),
        ],
    );
}

#[test]
fn machine_joins() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b INT, c TEXT, d REAL, e)",
            "CREATE INDEX t_b ON t(b)",
            "CREATE INDEX t_cb ON t(c, b DESC)",
            "CREATE TABLE u(x, y TEXT COLLATE NOCASE, z NUMERIC)",
            "CREATE INDEX u_x ON u(x)",
            "CREATE TABLE p(k TEXT, j INT, v, PRIMARY KEY(k, j DESC)) WITHOUT ROWID",
            "INSERT INTO t VALUES(1,5,'abc',1.5,NULL),(2,3,'ABC',NULL,'e2'),(3,5,'b1',2.0,3),(4,NULL,'abc',0.5,x'6162'),(5,1,NULL,1e3,5.25),(6,3,'a0','7',6),(7,7,'',-0.0,'7'),(9,2,'b1',2.5,9),(10,5,'abd',NULL,NULL),(12,'12','12',12,12)",
            "INSERT INTO u VALUES(5,'Foo',1),(3,'foo','2.0'),(5,'BAR',NULL),(NULL,'bar',3),('5','baz',1e2),(7,NULL,'z'),(1,'Foo',0)",
            "INSERT INTO p VALUES('k1',1,'v1'),('k1',2,NULL),('k2',1,5),('k0',9,1.5),('k2',7,'v1')",
        ],
        &[
            ("SELECT t.a, u.y FROM t JOIN u ON u.x = t.b", &["1|Foo", "3|Foo", "10|Foo", "2|foo", "6|foo", "1|BAR", "3|BAR", "10|BAR", "1|baz", "3|baz", "10|baz", "7|", "5|Foo"], None),
            ("SELECT t.a, u.rowid FROM t LEFT JOIN u ON u.x = t.a", &["4|", "5|1", "5|3", "5|5", "9|", "2|", "6|", "1|7", "3|2", "10|", "7|6", "12|"], None),
            ("SELECT t.a, u.x FROM t RIGHT JOIN u ON u.x = t.b", &["5|1", "2|3", "6|3", "1|5", "1|5", "1|5", "3|5", "3|5", "3|5", "10|5", "10|5", "10|5", "7|7", "|"], None),
            ("SELECT t.a, u.x FROM t FULL JOIN u ON u.x = t.a WHERE t.a IS NULL OR u.x IS NULL", &["4|", "9|", "2|", "6|", "10|", "12|", "|"], None),
            ("SELECT count(*) FROM t, u", &["70"], None),
            ("SELECT t.a, p.k FROM t JOIN p ON p.j = t.a ORDER BY p.k, t.a", &["9|k0", "1|k1", "2|k1", "1|k2", "7|k2"], None),
            ("SELECT x.a, y.a FROM t x JOIN t y ON y.b = x.a", &["1|5", "2|9", "3|2", "3|6", "5|1", "5|3", "5|10", "7|7", "12|12"], None),
            ("SELECT t.a, u.y, p.v FROM t JOIN u ON u.x = t.b JOIN p ON p.j = t.a", &["1|Foo|v1", "1|Foo|5", "2|foo|", "1|BAR|v1", "1|BAR|5", "1|baz|v1", "1|baz|5", "7||v1"], None),
            ("SELECT t.a FROM t JOIN u ON u.y = t.c", &[], None),
            ("SELECT a, y FROM t CROSS JOIN u WHERE u.z = t.d", &["3|foo", "7|Foo"], None),
        ],
    );
}

#[test]
fn machine_subqueries() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b INT, c TEXT, d REAL, e)",
            "CREATE INDEX t_b ON t(b)",
            "CREATE INDEX t_cb ON t(c, b DESC)",
            "CREATE TABLE u(x, y TEXT COLLATE NOCASE, z NUMERIC)",
            "CREATE INDEX u_x ON u(x)",
            "CREATE TABLE p(k TEXT, j INT, v, PRIMARY KEY(k, j DESC)) WITHOUT ROWID",
            "INSERT INTO t VALUES(1,5,'abc',1.5,NULL),(2,3,'ABC',NULL,'e2'),(3,5,'b1',2.0,3),(4,NULL,'abc',0.5,x'6162'),(5,1,NULL,1e3,5.25),(6,3,'a0','7',6),(7,7,'',-0.0,'7'),(9,2,'b1',2.5,9),(10,5,'abd',NULL,NULL),(12,'12','12',12,12)",
            "INSERT INTO u VALUES(5,'Foo',1),(3,'foo','2.0'),(5,'BAR',NULL),(NULL,'bar',3),('5','baz',1e2),(7,NULL,'z'),(1,'Foo',0)",
            "INSERT INTO p VALUES('k1',1,'v1'),('k1',2,NULL),('k2',1,5),('k0',9,1.5),('k2',7,'v1')",
        ],
        &[
            ("SELECT a FROM t WHERE b IN (SELECT x FROM u)", &["5", "2", "6", "1", "3", "10", "7"], None),
            ("SELECT a FROM t WHERE b NOT IN (SELECT x FROM u WHERE x IS NOT NULL)", &["9", "12"], None),
            ("SELECT a, (SELECT count(*) FROM u WHERE u.x = t.b) FROM t", &["4|0", "5|1", "9|0", "2|1", "6|1", "1|3", "3|3", "10|3", "7|1", "12|0"], None),
            ("SELECT a FROM t WHERE EXISTS (SELECT 1 FROM u WHERE u.x = t.a)", &["5", "1", "3", "7"], None),
            ("SELECT s.b, s.n FROM (SELECT b, count(*) AS n FROM t) AS s", &["|10"], None),
            ("SELECT * FROM (SELECT a, b FROM t ORDER BY b LIMIT 3) AS s WHERE s.a > 1", &["4|", "5|1", "9|2"], None),
            ("SELECT (SELECT c FROM t WHERE a = 3), (SELECT max(j) FROM p WHERE k = 'k2')", &["b1|7"], None),
            ("SELECT a FROM t WHERE (b, c) IN (SELECT x, y FROM u)", &[], None),
            ("SELECT a FROM t WHERE a IN (SELECT j FROM p) ORDER BY a DESC", &["9", "7", "2", "1"], None),
            ("SELECT count(*) FROM (SELECT DISTINCT b FROM t) AS s, (SELECT x FROM u LIMIT 2) AS q", &["14"], None),
        ],
    );
}

