#[test]
fn machine_expressions_affinity_and_functions() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b INT, c TEXT, d REAL, e)",
            "CREATE INDEX t_b ON t(b)",
            "CREATE INDEX t_cb ON t(c, b DESC)",
            "CREATE TABLE u(x, y TEXT COLLATE NOCASE, z NUMERIC)",
            "CREATE INDEX u_x ON u(x)",
            "CREATE TABLE p(k TEXT, j INT, v, PRIMARY KEY(k, j DESC)) WITHOUT ROWID",
            "INSERT INTO t VALUES(1,5,'abc',1.5,NULL),(2,3,'ABC',NULL,'e2'),(3,5,'b1',2.0,3),(4,NULL,'abc',0.5,x'6162'),(5,1,NULL,1e3,5.25),(6,3,'a0','7',6),(7,7,'',-0.0,'7'),(9,2,'b1',2.5,9),(10,5,'abd',NULL,NULL),(12,'12','12',12,12)",
            "INSERT INTO u VALUES(5,'Foo',1),(3,'foo','2.0'),(5,'BAR',NULL),(NULL,'bar',3),('5','baz',1e2),(7,NULL,'z'),(1,'Foo',0)",
            "INSERT INTO p VALUES('k1',1,'v1'),('k1',2,NULL),('k2',1,5),('k0',9,1.5),('k2',7,'v1')",
        ],
        &[
            ("SELECT a, b + d, b || c, d * 2, -b, b % 2, a / 0, b & 6, b << 2 FROM t WHERE a < 6", &["1|6.5|5abc|3.0|-5|1||4|20", "2||3ABC||-3|1||2|12", "3|7.0|5b1|4.0|-5|1||4|20", "4|||1.0|||||", "5|1001.0||2000.0|-1|1||0|4"], None),
            ("SELECT a FROM t WHERE b = '5'", &["1", "3", "10"], None),
            ("SELECT a FROM t WHERE c = 12", &["12"], None),
            ("SELECT a FROM t WHERE d = '7'", &["6"], None),
            ("SELECT a, CAST(c AS INT), CAST(d AS TEXT), CAST(e AS REAL) FROM t WHERE a > 5", &["6|0|7.0|6.0", "7|0|0.0|7.0", "9|0|2.5|9.0", "10|0||", "12|12|12.0|12.0"], None),
            ("SELECT a, typeof(b), typeof(d), typeof(e) FROM t", &["1|integer|real|null", "2|integer|null|text", "3|integer|real|integer", "4|null|real|blob", "5|integer|real|real", "6|integer|real|integer", "7|integer|real|text", "9|integer|real|integer", "10|integer|null|null", "12|integer|real|integer"], None),
            ("SELECT a, b IS NULL, c IS NOT NULL, b BETWEEN 2 AND 5, c IN ('abc', 'b1') FROM t", &["5|0|0|0|", "7|0|1|0|0", "12|0|1|0|0", "2|0|1|1|0", "6|0|1|1|0", "1|0|1|1|1", "4|1|1||1", "10|0|1|1|0", "3|0|1|1|1", "9|0|1|1|1"], None),
            ("SELECT a, CASE WHEN b > 4 THEN 'hi' WHEN b IS NULL THEN 'null' ELSE 'lo' END FROM t", &["4|null", "5|lo", "9|lo", "2|lo", "6|lo", "1|hi", "3|hi", "10|hi", "7|hi", "12|hi"], None),
            ("SELECT a, coalesce(b, d, 'x'), ifnull(c, 'n'), nullif(b, 5) FROM t", &["1|5|abc|", "2|3|ABC|3", "3|5|b1|", "4|0.5|abc|", "5|1|n|1", "6|3|a0|3", "7|7||7", "9|2|b1|2", "10|5|abd|", "12|12|12|12"], None),
            ("SELECT max(a, b), min(a, b), max(c, 'abd'), length(c), upper(c), abs(b), substr(c, 2) FROM t WHERE a IN (1, 2, 12)", &["5|1|abd|3|ABC|5|bc", "3|2|abd|3|ABC|3|BC", "12|12|abd|2|12|12|2"], None),
            ("SELECT a FROM t WHERE c = 'ABC' COLLATE NOCASE", &["2", "1", "4"], None),
            ("SELECT y FROM u WHERE y = 'foo'", &["Foo", "foo", "Foo"], None),
            ("SELECT hex(e), quote(e) FROM t WHERE a IN (4, 5, 7)", &["6162|X'6162'", "352E3235|5.25", "37|'7'"], None),
        ],
    );
}

#[test]
fn machine_runtime_errors_after_rows() {
    check(
        &[
            "CREATE TABLE t(a INTEGER PRIMARY KEY, b INT, c TEXT, d REAL, e)",
            "CREATE INDEX t_b ON t(b)",
            "CREATE INDEX t_cb ON t(c, b DESC)",
            "CREATE TABLE u(x, y TEXT COLLATE NOCASE, z NUMERIC)",
            "CREATE INDEX u_x ON u(x)",
            "CREATE TABLE p(k TEXT, j INT, v, PRIMARY KEY(k, j DESC)) WITHOUT ROWID",
            "INSERT INTO t VALUES(1,5,'abc',1.5,NULL),(2,3,'ABC',NULL,'e2'),(3,5,'b1',2.0,3),(4,NULL,'abc',0.5,x'6162'),(5,1,NULL,1e3,5.25),(6,3,'a0','7',6),(7,7,'',-0.0,'7'),(9,2,'b1',2.5,9),(10,5,'abd',NULL,NULL),(12,'12','12',12,12)",
            "INSERT INTO u VALUES(5,'Foo',1),(3,'foo','2.0'),(5,'BAR',NULL),(NULL,'bar',3),('5','baz',1e2),(7,NULL,'z'),(1,'Foo',0)",
            "INSERT INTO p VALUES('k1',1,'v1'),('k1',2,NULL),('k2',1,5),('k0',9,1.5),('k2',7,'v1')",
        ],
        &[
            ("SELECT a, abs(-9223372036854775807 - (a = 5)) FROM t", &["4|9223372036854775807"], Some("integer overflow")),
            ("SELECT a, like('a', 'b', iif(a = 3, 'xx', 'x')) FROM t", &["4|0", "5|0", "9|0", "2|0", "6|0", "1|0"], Some("ESCAPE expression must be a single character")),
            ("SELECT a FROM t ORDER BY a LIMIT 'x'", &[], Some("datatype mismatch")),
            ("SELECT a, abs(-9223372036854775807 - (a = 5)) FROM t ORDER BY b", &["4|9223372036854775807"], Some("integer overflow")),
            ("SELECT sum(iif(a = 9, 9223372036854775807, a)) FROM t", &[], Some("integer overflow")),
            ("SELECT a, (SELECT abs(-9223372036854775807 - (t.a = 2))) FROM t", &["4|9223372036854775807", "5|9223372036854775807", "9|9223372036854775807"], Some("integer overflow")),
        ],
    );
}

#[test]
fn machine_rows_with_overflow_pages() {
    check(
        &[
            "PRAGMA page_size=1024",
            "CREATE TABLE big(id INTEGER PRIMARY KEY, s TEXT, t TEXT)",
            "CREATE INDEX big_s ON big(s)",
            "INSERT INTO big VALUES(1, replace(hex(zeroblob(700)),'00','ab'), 'x'),(2, 'short', replace(hex(zeroblob(3000)),'00','yz')),(3, replace(hex(zeroblob(700)),'00','ab') || 'c', replace(hex(zeroblob(5000)),'00','q')),(4, NULL, replace(hex(zeroblob(40)),'00','r'))",
        ],
        &[
            ("SELECT id, length(s), length(t), typeof(t) FROM big", &["1|1400|1|text", "2|5|6000|text", "3|1401|5000|text", "4||40|text"], None),
            ("SELECT id, substr(t, 2990, 12) FROM big", &["1|", "2|zyzyzyzyzyzy", "3|qqqqqqqqqqqq", "4|"], None),
            ("SELECT id FROM big WHERE s > replace(hex(zeroblob(700)),'00','ab')", &["3", "2"], None),
            ("SELECT id FROM big ORDER BY s DESC", &["2", "3", "1", "4"], None),
            ("SELECT id, s = t, substr(s, 1395, 8) FROM big WHERE s IS NOT NULL", &["1|0|ababab", "2|0|", "3|0|abababc"], None),
            ("SELECT count(*), max(length(t)) FROM big WHERE s LIKE 'ab%'", &["2|5000"], None),
            ("SELECT a.id, b.id FROM big a JOIN big b ON b.s = a.s || 'c'", &["1|3"], None),
            ("SELECT id, t FROM big WHERE id = 4", &["4|rrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr"], None),
        ],
    );
}

#[test]
fn machine_sorter_larger_than_one_pma() {
    check(
        &[
            "PRAGMA page_size=512",
            "PRAGMA cache_size=5",
            "CREATE TABLE s(a INTEGER PRIMARY KEY, b INT, c TEXT)",
            "WITH RECURSIVE c(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM c WHERE x<4000) INSERT INTO s SELECT x, x%7, printf('%040d', x%13) FROM c",
        ],
        &[
            ("SELECT a FROM s ORDER BY b LIMIT 5 OFFSET 2000", &["1998", "2005", "2012", "2019", "2026"], None),
            ("SELECT a FROM s ORDER BY c DESC, b LIMIT 6 OFFSET 3990", &["3107", "3198", "3289", "3380", "3471", "3562"], None),
            ("SELECT count(*), min(a), max(a) FROM (SELECT a FROM s ORDER BY c, b DESC LIMIT 1000 OFFSET 1500)", &["1000|5|3998"], None),
            ("SELECT group_concat(a) FROM (SELECT a FROM s ORDER BY b LIMIT 12 OFFSET 570)", &["3997,1,8,15,22,29,36,43,50,57,64,71"], None),
            ("SELECT a, b FROM s ORDER BY b DESC, c LIMIT 4 OFFSET 2500", &["3579|2", "3670|2", "3761|2", "3852|2"], None),
        ],
    );
}
